def transform(grid):
    from collections import Counter
    a=[row[:] for row in grid]
    counts=Counter(v for row in a for v in row)
    bg=counts.most_common(1)[0][0]
    color=max((v for v in counts if v != bg), key=lambda v: counts[v])
    points=[(r,c) for r,row in enumerate(a) for c,v in enumerate(row) if v==color]
    rmin=min(r for r,c in points); rmax=max(r for r,c in points)
    cmin=min(c for r,c in points); cmax=max(c for r,c in points)
    h,w=len(a),len(a[0])
    for r in range(h):
        cols=[c for c in range(w) if a[r][c]==color]
        if len(cols)>=2:
            for c in range(cmin,cmax+1):
                if a[r][c]==bg: a[r][c]=2
    for c in range(w):
        rows=[r for r in range(h) if a[r][c]==color]
        if len(rows)>=2:
            for r in range(rmin,rmax+1):
                if a[r][c]==bg: a[r][c]=2
    return a
